import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gelu(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_scalar(float x) {
    const float k0 = 0.7978845608028654f; // sqrt(2/pi)
    const float k1 = 0.044715f;
    // Fused multiply-adds reduce temporary registers and instruction count.
    float inner = k0 * fmaf(k1 * x * x, x, x);
    // Fast tanh via sigmoid identity using fast intrinsics: tanh(z) = 2*sigmoid(2z)-1
    float t = __fdividef(2.0f, __fmaf_rn(1.0f, __expf(-2.0f * inner), 1.0f)) - 1.0f;
    return 0.5f * fmaf(x, t, x);
}

__global__ void __launch_bounds__(256, 4) cute_gelu_kernel_vec4(
    const float4* __restrict__ in, float4* __restrict__ out, int N4)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int i = idx;
    // Unroll by 4 to increase instruction-level parallelism and amortize
    // loop overhead / index arithmetic across multiple loads/stores.
    int stride4 = 4 * stride;
    for (; i + 3 * stride < N4; i += stride4) {
        float4 v0 = __ldg(&in[i]);
        float4 v1 = __ldg(&in[i + stride]);
        float4 v2 = __ldg(&in[i + 2 * stride]);
        float4 v3 = __ldg(&in[i + 3 * stride]);
        float4 r0, r1, r2, r3;
        r0.x = gelu_scalar(v0.x); r0.y = gelu_scalar(v0.y); r0.z = gelu_scalar(v0.z); r0.w = gelu_scalar(v0.w);
        r1.x = gelu_scalar(v1.x); r1.y = gelu_scalar(v1.y); r1.z = gelu_scalar(v1.z); r1.w = gelu_scalar(v1.w);
        r2.x = gelu_scalar(v2.x); r2.y = gelu_scalar(v2.y); r2.z = gelu_scalar(v2.z); r2.w = gelu_scalar(v2.w);
        r3.x = gelu_scalar(v3.x); r3.y = gelu_scalar(v3.y); r3.z = gelu_scalar(v3.z); r3.w = gelu_scalar(v3.w);
        // Streaming (cache-bypassing) stores: the output tensor is write-only and
        // will not be re-read soon by this kernel, so avoid polluting L1/L2 caches
        // and improve effective write bandwidth.
        __stcs(&out[i], r0);
        __stcs(&out[i + stride], r1);
        __stcs(&out[i + 2 * stride], r2);
        __stcs(&out[i + 3 * stride], r3);
    }
    for (; i < N4; i += stride) {
        // Use __ldg for read-only cached load through the texture/L1 read-only path,
        // reducing memory latency for the strictly read-only input tensor.
        float4 v = __ldg(&in[i]);
        float4 r;
        r.x = gelu_scalar(v.x);
        r.y = gelu_scalar(v.y);
        r.z = gelu_scalar(v.z);
        r.w = gelu_scalar(v.w);
        __stcs(&out[i], r);
    }
}

__global__ void __launch_bounds__(256, 4) cute_gelu_kernel_scalar(
    const float* __restrict__ in, float* __restrict__ out, int N)
{
    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(N), make_stride(Int<1>{}));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(N), make_stride(Int<1>{}));

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < N; i += stride) {
        gOut(i) = gelu_scalar(gIn(i));
    }
}

torch::Tensor cute_gelu(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Expect float32 tensor");

    auto x_c = x.contiguous();
    auto out = torch::empty_like(x_c);

    int64_t N = x_c.numel();
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    int device;
    cudaGetDevice(&device);
    int smCount = 0;
    cudaDeviceGetAttribute(&smCount, cudaDevAttrMultiProcessorCount, device);
    if (smCount <= 0) smCount = 1;
    if (N % 4 == 0) {
        int N4 = (int)(N / 4);
        int threads = 256;
        // Launch a grid sized to keep SMs saturated (matching the __launch_bounds__(512, 2)
        // occupancy target) while intentionally under-subscribing total threads relative to
        // N4 so the unroll-by-4 grid-stride loop actually executes multiple iterations per
        // thread, amortizing loop/index overhead and improving ILP and effective bandwidth.
        int max_blocks_for_occupancy = smCount * 4; // matches min blocks/SM in launch_bounds
        int full_blocks = (N4 + threads - 1) / threads;
        int blocks = full_blocks < max_blocks_for_occupancy ? full_blocks : max_blocks_for_occupancy;
        if (blocks < 1) blocks = 1;
        if (blocks > 65535) blocks = 65535;
        cute_gelu_kernel_vec4<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            N4);
    } else {
        int threads = 256;
        int max_blocks_for_occupancy = smCount * 4;
        int full_blocks = (int)((N + threads - 1) / threads);
        int blocks = full_blocks < max_blocks_for_occupancy ? full_blocks : max_blocks_for_occupancy;
        if (blocks < 1) blocks = 1;
        if (blocks > 65535) blocks = 65535;
        cute_gelu_kernel_scalar<<<blocks, threads, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), (int)N);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE gelu launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_gelu_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gelu"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, x):
        return self._ext.cute_gelu(x)

